  ('elena-v', 7, 'Elena V.', 63, 'donna', 'Bologna', array['Senior', 'Commercial']::text[], array['capelli bianchi', 'elegante', 'nonna']::text[], 'Modella senior per campagne pharma, travel e lifestyle. Eleganza senza tempo.', 5, 41, 85, array['#e11d48', '#881337']::text[]),
